import moment from 'moment';
import { STEP_VALUES } from 'Common/Components/SeverityRange/constants';

export const getRelativeTime = (date) => {
  const diff = moment().diff(moment(date), 'minutes');
  if (diff < 60) return `${diff}m`;
  if (diff < 1440) return `${Math.floor(diff / 60)}h`;
  return `${Math.floor(diff / 1440)}d`;
};

export const buildExposureDetail = (vuln) => {
  const data = vuln.value || {};
  const cwe = Array.isArray(data.cwe) ? data.cwe.join(', ') : data.cwe || '';
  const method = data.method || '';
  const path = data.path || '';
  return [cwe, method, path].filter(Boolean).join(' · ');
};

export const getSeverityInfo = (severity = {}) => {
  const normalized = severity?.toLowerCase();
  const info = STEP_VALUES.find(({ parsedSeverity }) => parsedSeverity === normalized) || STEP_VALUES[0];
  return { ...info, shortLabel: info.label.charAt(0) };
};

const MAX_VISIBLE_TAGS = 2;

export const getVisibleTags = (tags = [], max = MAX_VISIBLE_TAGS) => ({
  visible: tags.slice(0, max),
  overflow: tags.slice(max),
  extraCount: Math.max(0, tags.length - max)
});
