import React from 'react';
import { Title, TitleContainer, TitleInfo, Wrapper, IconWrapper } from './styled';

const TitleWrapper = ({ title, info = null, icon = null }) => {
  return (
    <Wrapper>
      <TitleContainer>
        {icon && <IconWrapper>{icon}</IconWrapper>}
        <Title>{title}</Title>
      </TitleContainer>
      {info && <TitleInfo>{info}</TitleInfo>}
    </Wrapper>
  );
};

export default TitleWrapper;
